    if (d[i + 3] < 20 || d[i] > 40 || d[i + 1] > 40 || d[i + 2] > 55) continue;
    const open = (xx, yy) => xx >= 0 && yy >= 0 && xx < w && yy < h && d[(yy * w + xx) * 4 + 3] > 20;
