    if (solid(nx, ny) || warpAt(nx, ny)) continue;
    const path = (nx === S.world.x && ny === S.world.y) ? [] : findPath([{ x: nx, y: ny }]);
    if (!path) continue;
    const d = Math.hypot((nx + 0.5) * TS - cx, (ny + 0.5) * TS - cy);
