    x: anchor.x, y: anchor.y, dir: turned.dir, dist: dist, shown: shown, tracked: !!tracked, rail: false,
    box: { x: (pos.x - half) * css, y: (pos.y - half) * css, w: CUE_EDGE.box, h: CUE_EDGE.box },
