  const q = objPos(o), fx = q.fx != null ? q.fx : q.x, fy = q.fy != null ? q.fy : q.y, X = Math.round(fx * TS - cx), Y = Math.round(fy * TS - cy);
  if (X < -26 || Y < -24 || X > VW + 10 || Y > VH + 2) return;
