  const motes = $('#rvMotes'); if (motes) motes.innerHTML = '';
  const ban = $('#rvBanner'); if (ban && !ban.hidden) ban.style.transform = 'scale(1)';
  const el = $('#ovReveal'); if (el && !el.hidden) el.style.opacity = '1';
