  if (calm) {
    showCardGlyph('emote_ask');
    fxLater(900, () => { if (reveal.phase === 'open') showCardGlyph('emote_heart'); });
    revealChirp();
    return;
  }
  el.style.opacity = '0';
  requestAnimationFrame(() => { if (!el.hidden && reveal.phase === 'open') el.style.opacity = '1'; });
  showCardGlyph('emote_ask');
  fxLater(900, () => { if (reveal.phase === 'open') showCardGlyph('emote_heart'); });
