  for (const e of sceneEmotes) {
    const o = emoteTarget(e.who); if (!o || !GLYPH[e.glyph]) continue;
    const q = objPos(o);
    drawGlyph(g, e.glyph, Math.round(q.x * TS - cx) + 4, Math.round(q.y * TS - cy) - 15);
  }
