  renderWalklingActions(p);
  const nickEl = $('#wlNick');
  if (nickEl && document.activeElement !== nickEl) nickEl.value = cleanNick(p.nick);
  renderWalklingMoves(p);
  renderWalklingUse(p);
  renderWalklingRelease(p);
