function fillErrorList(){
  const box = $('#dbgErrors'); if (!box) return;
  const show = debugQueryOn();
  box.hidden = !show;
  const ol = $('#dbgErrorList'); if (!ol) return;
  ol.textContent = '';
  if (!show) return;
  for (const e of errorLog()) {
    const li = document.createElement('li');
    let when = ''; try { when = new Date(e.at).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }); } catch (err) {}
    const where = e.screen ? 'on ' + e.screen : '';
    li.textContent = [when, e.build || '', where, e.message || '', e.stack || ''].filter(Boolean).join(' · ');
    ol.appendChild(li);
  }
}
function fillReloadList(){
  const box = $('#dbgReloads'); if (!box) return;
  const show = debugQueryOn();
  box.hidden = !show;
  const ol = $('#dbgReloadList'); if (!ol) return;
  ol.textContent = '';
  if (!show) return;
  const list = lsJson(RELOAD_LAST);
  if (!Array.isArray(list)) return;
  for (const e of list) {
    if (!e || typeof e !== 'object') continue;
    const li = document.createElement('li');
    li.textContent = Object.keys(e).map(k => k + ' ' + (typeof e[k] === 'boolean' ? (e[k] ? 'yes' : 'no') : String(e[k]))).join(' · ');
    ol.appendChild(li);
  }
}
function bindDebugUi(){
  $('#setDebug').addEventListener('click', () => {
    sfx('tap');
    if (DEBUG) { closeSettings(); openDebug(); return; }
    const g = $('#dbgGate'); g.hidden = !g.hidden; renderDebugGate();
    if (!g.hidden) $('#dbgPass').focus();
  });
  $('#dbgUnlock').addEventListener('click', tryDebugUnlock);
  $('#dbgPass').addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); tryDebugUnlock(); } });
  $('#dbgTag').addEventListener('click', () => { if (!DEBUG) return; if (!debugOpen()) openDebug(); else closeDebug(); });
}
// The debug panel's own controls: bound once, right after debug_ui.js's markup is put in the page (debug sessions only).
function bindDebugPanel(){
  $('#dbgClose').addEventListener('click', () => { sfx('tap'); closeDebug(); });
  $('#dbgMusicPlay').addEventListener('click', () => {
    const id = $('#dbgMusicId').value;
    const ok = PPSound.music(id, { fadeOut: 180, fadeIn: 180 });
    debugOut(ok ? 'Playing ' + id + '.' : 'No loop.');
  });
  $('#dbgMusicBack').addEventListener('click', () => {
    const id = trackFor(CUR);
    if (id) PPSound.music(id, { fadeOut: 180, fadeIn: 180 });
    debugOut(id ? 'Back to ' + id + '.' : 'This place has no loop.');
  });
  $('#ovDebug').addEventListener('click', e => { if (e.target === e.currentTarget) closeDebug(); });
  $('#dbgLock').addEventListener('click', () => { setDebugEnabled(false); closeDebug(); toast('Debug mode off.'); });
  const dbgGrant = $('#dbgGrant');
  if (dbgGrant) dbgGrant.addEventListener('click', () => {
    const id = $('#dbgGrantId') ? $('#dbgGrantId').value : '';
    const fn = window.PixelPets && PixelPets[dbgGrant.dataset.api];
    if (typeof fn !== 'function') { debugOut('Debug is off.'); return; }
    debugOut(fn(id) ? 'Granted ' + id + '.' : 'No such look.');
  });
  $('#dbgGoCheckpoint').addEventListener('click', () => {
    const r = applyCheckpoint($('#dbgCheckpoint').value);
    if (!r.ok) debugOut(debugWhy(r.reason));
  });
  $('#dbgGiveItem').addEventListener('click', () => {
    const id = $('#dbgItem').value, n = Math.max(1, $('#dbgItemN').value | 0), c = debugGiveItem(id, n);
    debugOut((ITEMS[id] ? ITEMS[id].name : id) + ' ×' + c + '.');
  });
  $('#dbgSetAcorns').addEventListener('click', () => {
    S.money = Math.max(0, $('#dbgAcorns').value | 0); save(); debugOut(acorns(S.money) + '.');
  });
  for (const id of ['dbgSpecies', 'dbgStage', 'dbgLevel', 'dbgHp']) {
    const el = $('#' + id); if (!el) continue;
    el.addEventListener('change', renderEncPreview); el.addEventListener('input', renderEncPreview);
  }
  $('#dbgSpawnEnc').addEventListener('click', () => {
    const r = spawnEncounter(readEncOpts());
    if (!r.ok) debugOut(debugWhy(r.reason));
  });
  $('#dbgPlaceWild').addEventListener('click', () => {
    const r = spawnEncounter(Object.assign({ onMap: true }, readEncOpts()));
    if (!r.ok) { debugOut(debugWhy(r.reason)); return; }
    dismissForDebug(); showTab('walk');
    toast(r.preview.name + ' is on the map.');
  });
  $('#dbgSideKeepers').addEventListener('click', () => { const r = setFaction('keepers'); renderDebugPanel(); toast('Pledged to ' + STANDING_CFG.sides[r.side].name + '.'); });
  $('#dbgSideGlimmer').addEventListener('click', () => { const r = setFaction('glimmer'); renderDebugPanel(); toast('Pledged to ' + STANDING_CFG.sides[r.side].name + '.'); });
  const setMeter = (sd, input) => {
    const n = setStanding(sd, +$(input).value);
    if (n == null) return;
    save(); renderDebugPanel(); toast(STANDING_CFG.sides[sd].short + ' standing ' + n + '.');
  };
  $('#dbgSetKeepers').addEventListener('click', () => setMeter('keepers', '#dbgKeepersPts'));
  $('#dbgSetGlimmer').addEventListener('click', () => setMeter('glimmer', '#dbgGlimmerPts'));
  $('#dbgHeal').addEventListener('click', () => { debugHeal(); toast('Team healed.'); });
  $('#dbgFillCare').addEventListener('click', () => { debugSetCare({ hunger: 100, happy: 100, energy: 100, all: true }); toast('Care filled.'); });
  $('#dbgFast').addEventListener('click', () => { setFast(!fastMode); renderDebugPanel(); });
  $('#dbgSetLevel').addEventListener('click', () => { const r = debugSetLevel(+$('#dbgPetLevel').value); if (r) debugOut('Partner Lv ' + r.level + '.'); });
  $('#dbgResetCaps').addEventListener('click', () => { const p = pet(); if (!p) return; delete p.cx; delete p.ex; delete S.flags[BOWL.flag]; updateHUD(); save(); toast('Daily XP caps reset.'); });
  $('#dbgSkip').addEventListener('click', () => {
    const sec = Math.max(0, +$('#dbgHours').value || 0) * 3600;
    catchUp(sec); regenAll(sec); updateHUD(); save(); debugOut('Skipped ' + (+$('#dbgHours').value || 0) + ' h.');
  });
  $('#dbgWarp').addEventListener('click', () => {
    const map = $('#dbgMap').value;
    const busy = debugBusy(); if (busy) { debugOut(debugWhy(busy)); return; }
    if (!WORLD[map]) { debugOut(debugWhy('map')); return; }
    dismissForDebug(); showTab('walk');
    const m = WORLD[map], sp = m.start || m.safe || { x: 1, y: 1 };
    arriveAt({ map, x: sp.x, y: sp.y, facing: sp.facing || 'down' });
    toast('Now in ' + (m.name || map) + '.');
  });
  $('#dbgRunScene').addEventListener('click', () => {
    const id = $('#dbgScene').value.trim();
    if (!sceneSteps(id) || scene) { debugOut(scene ? debugWhy('scene') : 'No scene "' + id + '".'); return; }
    dismissForDebug(); showTab('walk'); runScene(id);
  });
  $('#dbgSetFlag').addEventListener('click', () => {
    const k = $('#dbgFlag').value.trim(); if (!k) return;
    const v = debugFlagValue($('#dbgFlagVal').value);
    if (v === null) delete S.flags[k]; else S.flags[k] = v;
    save(); syncSide(); debugOut(k + ' = ' + String(S.flags[k]));
  });
  $('#dbgClearFlag').addEventListener('click', () => {
    const k = $('#dbgFlag').value.trim(); if (!k) return;
    delete S.flags[k]; save(); syncSide(); debugOut('Cleared ' + k + '.');
  });
  $('#dbgForceTrainer').addEventListener('click', () => {
    const id = $('#dbgTrainer').value;
    const busy = debugBusy(); if (busy) { debugOut(debugWhy(busy)); return; }
    if (!TRAINERS[id]) { debugOut('Unknown trainer.'); return; }
    if ($('#dbgRematch').checked) delete S.flags['trainer.' + id];
    else if (S.flags['trainer.' + id]) { debugOut('Already beaten. Turn on rematch.'); return; }
    dismissForDebug(); showTab('walk');
    if (!openBattle({ kind: 'trainer', trainerId: id })) debugOut('Could not start that battle.');
  });
  $('#dbgWin').addEventListener('click', () => { if (!battle.on) { debugOut('No battle is open.'); return; } closeDebug(); finish('win', battle.id); });
  $('#dbgLose').addEventListener('click', () => { if (!battle.on) { debugOut('No battle is open.'); return; } closeDebug(); finish('tired', battle.id); });
  $('#dbgSetFoeHp').addEventListener('click', () => { if (debugSetHp('foe', +$('#dbgFoeHp').value)) renderDebugPanel(); });
  $('#dbgSetMyHp').addEventListener('click', () => { if (debugSetHp('me', +$('#dbgMyHp').value)) renderDebugPanel(); });
  $('#dbgKit').addEventListener('click', () => { const r = fillKit(); debugOut('Kit ready. ' + acorns(r.money) + '.'); });
  $('#dbgSight').addEventListener('click', () => { sightShown = !sightShown; debugOut(sightShown ? 'Sight lines on.' : 'Sight lines off.'); });
  $('#dbgEndScene').addEventListener('click', () => { if (!scene) { debugOut('No scene is open.'); return; } scene.skip = true; closeDebug(); });
  $('#dbgTextSpeed').addEventListener('change', () => debugSetTextSpeed($('#dbgTextSpeed').value));
  $('#dbgBoothGo').addEventListener('click', () => {
    const id = $('#dbgBooth').value;
    const busy = debugBusy(); if (busy) { debugOut(debugWhy(busy)); return; }
    dismissForDebug(); showTab('walk');
    const o = Object.values(WORLD).reduce((a, m) => a.concat(m.objs || []), []).find(x => x.booth === id);
    if (!o) { debugOut('No booth for ' + id + '.'); return; }
    openBooth(o);
  });
  $('#dbgClearHold').addEventListener('click', () => { debugHeal(); toast('Lantern hold cleared.'); });
  $('#dbgChecks').addEventListener('click', () => {
    const d = devChecks();
    const bad = Object.entries(d).reduce((a, [k, v]) => a.concat((v || []).map(s => k + ': ' + s)), []);
    debugOut(bad.length ? bad.join('\n') : 'All dev checks passed.', true);
    if (!bad.length) toast('All dev checks passed.');
  });
  $('#dbgSnap').addEventListener('click', () => {
    const text = JSON.stringify(debugSnapshot(), null, 2);
    debugOut(text, true); toast('Snapshot ready.');
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).catch(() => {});
  });
}

/* ---------- partner tray (PARTNER_CARE D541-D547) ---------- */
let trayPartyKey = '';
const trayOpen = () => { const el = $('#careTray'); return !!(el && !el.hidden); };
function closePartnerTray(){
  const el = $('#careTray'); if (!el || el.hidden) return;
  const resumeId = tut.lesson === 'care' ? String(tut.id || '').replace(/x$/, '') : '';
  el.hidden = true; el.classList.remove('ct-multi'); document.body.classList.remove('ct-open');
  if (tut.lesson === 'care' && (careLes.phase === 'tray' || careLes.replay)) {
    if (careLes.replay && resumeId) careLes.replayStep = resumeId;
    lessonHide();
    careLes.phase = 'paused';
    if (!careLes.replay) scheduleTutorial(true);
  }
}
function paintTrayBadge(c, q){
  const g = ctx(c); g.clearRect(0, 0, 5, 5);
  let glyph = '';
  if (isFainted(q)) glyph = 'z';
  else {
    const n = partnerNeed(q);
    if (n) glyph = n.kind === 'food' ? 'badge_food' : n.kind === 'hurt' ? 'ico_hp' : 'ico_nrg';
  }
  c.hidden = !glyph;
  c.dataset.need = glyph;
  if (glyph) drawGlyph(g, glyph, 0, 0);
}
function renderPartnerTray(){
  const el = $('#careTray'); if (!el || el.hidden || !S) return;
  const p = pet(); if (!p) { closePartnerTray(); return; }
  const name = $('#ctName'), label = petName(p) + ' Lv ' + levelOf(p);
  if (name && name.textContent !== label) name.textContent = label;
  const row = $('#ctParty'); if (!row) return;
  el.classList.toggle('ct-multi', S.party.length >= 2);
  if (S.party.length < 2) { row.hidden = true; row.textContent = ''; trayPartyKey = ''; return; }
  row.hidden = false;
  const key = S.party.map(q => q.id).join(',');
  if (key !== trayPartyKey) {
    trayPartyKey = key; row.textContent = '';
    S.party.forEach(q => {
      const b = document.createElement('button'); b.type = 'button'; b.className = 'ct-slot'; b.dataset.id = q.id;
      const cv = document.createElement('canvas'); cv.width = cv.height = 18;
      const badge = document.createElement('canvas'); badge.width = badge.height = 5; badge.className = 'ct-badge'; badge.hidden = true;
      b.append(cv, badge);
      b.addEventListener('click', () => trayPick(q.id));
      row.appendChild(b);
    });
  }
  [...row.children].forEach(b => {
    const q = S.party.find(x => x.id === b.dataset.id); if (!q) return;
    const on = q.id === p.id;
    b.classList.toggle('on', on);
    b.setAttribute('aria-label', on ? petName(q) + ', your partner' : 'Make ' + petName(q) + ' your partner');
    spriteCanvas(b.querySelector('canvas'), spi(q), q.stage, 'n', isFaded(q), q.accessory);
    paintTrayBadge(b.querySelector('.ct-badge'), q);
  });
}
function openPartnerTray(){
  if (!S || !pet() || !$('#careTray')) return;
  $('#careTray').hidden = false;
  document.body.classList.add('ct-open');
  renderPartnerTray();
  careOnTrayOpen();
}
function trayPick(id){ partnerFromTap(id); }
// GEAR_SWITCH D772. The care-screen slots and the walk tray share this path.
function partnerFromTap(id){
  const before = pet();
  makePartner(id);
  const p = pet();
  if (!p || p.id !== id) { renderPartnerTray(); renderCareSwitch(); return false; }
  if (!before || before.id !== id) sfx('tap');
  toast(petName(p) + ' is your partner now!');
  save(); updateHUD();
  renderPartnerTray();
  return true;
}
function careSwitchOff(){
  if (!S) return true;
  if (document.body.classList.contains('nav-locked')) return true;
  if (tut.on) return true;
  if (overlayOpen()) return true;
  if (now() < anim.busyUntil) return true;
  return false;
}
function careSwitchTap(id){
  if (careSwitchOff()) { sfx('denied'); return; }
  partnerFromTap(id);
}
function renderCareSwitch(){
  const row = $('#petSlots'), wrap = $('#petSwitch');
  if (!row || !wrap) return;
  const party = (S && S.party) || [];
  const show = party.length >= 2;
  wrap.classList.toggle('empty', !show);
  if (!show) { row.hidden = true; row.textContent = ''; careSwitchKey = ''; wrap.classList.remove('fit'); }
  else {
    row.hidden = false;
    const key = party.map(q => q.id).join(',');
    if (key !== careSwitchKey) {
      careSwitchKey = key; row.textContent = '';
      party.forEach(q => {
        const b = document.createElement('button'); b.type = 'button'; b.className = 'pet-slot'; b.dataset.id = q.id;
        const cv = document.createElement('canvas'); cv.width = cv.height = 18; cv.className = 'sp';
        const badge = document.createElement('canvas'); badge.width = badge.height = 5; badge.className = 'bd'; badge.hidden = true;
        b.append(cv, badge);
        b.addEventListener('click', () => careSwitchTap(q.id));
        row.appendChild(b);
      });
    }
    const scr = $('#scr-pet'), back = wrap.querySelector('.scr-back');
    const backShown = !!(back && getComputedStyle(back).display !== 'none');
    let room = 0;
    if (scr) {
      const cs = getComputedStyle(scr);
      room = scr.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0);
    }
    const n = party.length, need = 44 + 6 + n * 44 + (n - 1) * 6;
    if (scr && scr.clientWidth > 0) wrap.classList.toggle('fit', n === 6 && backShown && need > room);
    const off = careSwitchOff(), cur = S && S.partnerId;
    [...row.children].forEach(b => {
      const q = party.find(x => x.id === b.dataset.id); if (!q) return;
      const on = q.id === cur;
      b.classList.toggle('on', on);
      b.setAttribute('aria-label', 'Switch to ' + petName(q));
      if (on) b.setAttribute('aria-current', 'true'); else b.removeAttribute('aria-current');
      if (off) b.setAttribute('aria-disabled', 'true'); else b.removeAttribute('aria-disabled');
      spriteCanvas(b.querySelector('canvas.sp'), spi(q), q.stage, 'n', isFaded(q), q.accessory);
      paintTrayBadge(b.querySelector('canvas.bd'), q);
    });
  }
  if (now() < anim.busyUntil) {
    const token = ++careSwitchWake, wait = anim.busyUntil - now();
    setTimeout(() => { if (token === careSwitchWake) renderCareSwitch(); }, Math.max(0, wait) + 40);
  }
  const present = document.body.classList.contains('ctl-modern') || show;
  if (!careSwitchLock && screen === 'pet' && careSwitchPresent !== null && present !== careSwitchPresent) {
    careSwitchPresent = present;
    careSwitchLock = 1;
    try { fitPetScene(); } finally { careSwitchLock = 0; }
  } else careSwitchPresent = present;
}

/* ---------- input ---------- */
