  $('#regionCanvas').addEventListener('wheel', e => { if (!$('#ovMap').hidden) e.preventDefault(); }, { passive: false });
  const roomLv = $('#mapLevelRoom'), townLv = $('#mapLevelTown'), regLv = $('#mapLevelRegion');
